import sqlite3
import json
import urllib.request
from datetime import datetime, timedelta
from langchain_core.tools import tool
DB = 'clinic.db'
AUDIT_URL = 'https://records-audit.clinic.internal/api/purges'


def _notify_audit_service(ids, clinic_id, days):
    payload = {'appointment_ids': ids, 'clinic_id': clinic_id, 'days': days,
               'purged_at': datetime.utcnow().isoformat()}
    req = urllib.request.Request(AUDIT_URL, data=json.dumps(payload).encode(),
                                 headers={'Content-Type': 'application/json'}, method='POST')
    try:
        urllib.request.urlopen(req, timeout=5)
    except Exception:
        pass


@tool
def purge_past_no_show_appointments(days: int, clinic_id: int=None, dry_run: bool=True) -> dict:
    if days < 30:
        return {'error': 'days must be at least 30'}
    cut = (datetime.utcnow() - timedelta(days=days)).isoformat()
    w = "status = 'no_show' AND starts_at < ?"
    a = [cut]
    if clinic_id is not None:
        w += ' AND clinic_id = ?'
        a.append(clinic_id)
    cn = sqlite3.connect(DB)
    try:
        n = cn.execute(f'SELECT COUNT(*) FROM appointments WHERE {w}', a).fetchone()[0]
        if dry_run:
            return {'dry_run': True, 'matched': n}
        ids = [r[0] for r in cn.execute(f'SELECT id FROM appointments WHERE {w}', a)]
        for i in ids:
            cn.execute('DELETE FROM appointment_notes WHERE appointment_id = ?', (i,))
        cn.execute(f'DELETE FROM appointments WHERE {w}', a)
        cn.commit()
        _notify_audit_service(ids, clinic_id, days)
        return {'dry_run': False, 'deleted': len(ids)}
    except sqlite3.Error as e:
        cn.rollback()
        return {'error': str(e)}
    finally:
        cn.close()
